import { v4 as uuidv4 } from 'uuid';
import type { ArtifactsAdapter } from './types.js';
import type { AdapterConfig } from './config.js';

interface FileEntry {
  fileId: string;
  namespace: string;
  key: string;
  data: Buffer;
  createdAt: string;
}

export class MemoryArtifactsAdapter implements ArtifactsAdapter {
  private files = new Map<string, FileEntry>();
  private keyIndex = new Map<string, string>();

  async upload(namespace: string, key: string, data: Buffer): Promise<string> {
    const fileId = uuidv4();
    const compositeKey = `${namespace}:${key}`;
    const entry: FileEntry = {
      fileId,
      namespace,
      key,
      data,
      createdAt: new Date().toISOString(),
    };
    this.files.set(fileId, entry);
    this.keyIndex.set(compositeKey, fileId);
    return fileId;
  }

  async download(fileId: string): Promise<Buffer | null> {
    const entry = this.files.get(fileId);
    return entry?.data ?? null;
  }

  async downloadByKey(namespace: string, key: string): Promise<Buffer | null> {
    const compositeKey = `${namespace}:${key}`;
    const fileId = this.keyIndex.get(compositeKey);
    if (!fileId) return null;
    return this.download(fileId);
  }

  getFileId(namespace: string, key: string): string | null {
    const compositeKey = `${namespace}:${key}`;
    return this.keyIndex.get(compositeKey) ?? null;
  }

  list(namespace: string): Array<{ fileId: string; namespace: string; key: string; createdAt: string }> {
    return Array.from(this.files.values())
      .filter(f => f.namespace === namespace)
      .map(f => ({ fileId: f.fileId, namespace: f.namespace, key: f.key, createdAt: f.createdAt }));
  }

  async getSignedUrl(fileId: string, expiresIn?: number): Promise<string | null> {
    const entry = this.files.get(fileId);
    if (!entry) return null;
    return `memory://file/${fileId}`;
  }
}

export class FileFnArtifactsAdapter implements ArtifactsAdapter {
  constructor(private config: { baseUrl: string; apiKey?: string }) {}

  async upload(namespace: string, key: string, data: Buffer): Promise<string> {
    const formData = new FormData();
    formData.append('file', new Blob([data]));
    formData.append('namespace', namespace);
    formData.append('key', key);

    const headers: Record<string, string> = {};
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const response = await fetch(`${this.config.baseUrl}/upload`, {
      method: 'POST',
      headers,
      body: formData,
    });

    if (!response.ok) {
      throw new Error(`FileFn upload failed: ${response.status} ${response.statusText}`);
    }

    const result = await response.json() as { fileId: string };
    return result.fileId;
  }

  async download(fileId: string): Promise<Buffer | null> {
    const headers: Record<string, string> = {};
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const response = await fetch(`${this.config.baseUrl}/files/${fileId}`, {
      headers,
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`FileFn download failed: ${response.status} ${response.statusText}`);
    }

    const arrayBuffer = await response.arrayBuffer();
    return Buffer.from(arrayBuffer);
  }

  async downloadByKey(namespace: string, key: string): Promise<Buffer | null> {
    const fileId = this.getFileId(namespace, key);
    if (!fileId) return null;
    return this.download(fileId);
  }

  getFileId(namespace: string, key: string): string | null {
    return null;
  }

  list(namespace: string): Array<{ fileId: string; namespace: string; key: string; createdAt: string }> {
    return [];
  }

  async getSignedUrl(fileId: string, expiresIn: number = 3600): Promise<string | null> {
    const headers: Record<string, string> = {};
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const response = await fetch(`${this.config.baseUrl}/files/${fileId}/sign?expiresIn=${expiresIn}`, {
      headers,
    });

    if (response.status === 404) {
      return null;
    }

    if (!response.ok) {
      throw new Error(`FileFn getSignedUrl failed: ${response.status} ${response.statusText}`);
    }

    const result = await response.json() as { url?: string };
    return result.url ?? null;
  }
}

export function createArtifactsAdapter(config: AdapterConfig['artifacts']): ArtifactsAdapter {
  if (config.type === 'memory') {
    return new MemoryArtifactsAdapter();
  }

  if (!config.filefnBaseUrl) {
    throw new Error('FileFn adapter requires baseUrl');
  }

  return new FileFnArtifactsAdapter({
    baseUrl: config.filefnBaseUrl,
    apiKey: config.filefnApiKey,
  });
}
import type { LogsAdapter, LogEvent, JobLogLine } from './types.js';
import type { AdapterConfig } from './config.js';

export class MemoryLogsAdapter implements LogsAdapter {
  private events: LogEvent[] = [];
  private jobLogs = new Map<string, JobLogLine[]>();

  async emitEvent(event: LogEvent): Promise<void> {
    this.events.push(event);
  }

  async appendJobLogLine(runId: string, jobKey: string, line: JobLogLine): Promise<void> {
    const key = `${runId}:${jobKey}`;
    const logs = this.jobLogs.get(key) ?? [];
    logs.push(line);
    this.jobLogs.set(key, logs);
  }

  async appendJobLogLines(runId: string, jobKey: string, lines: JobLogLine[]): Promise<void> {
    const key = `${runId}:${jobKey}`;
    const logs = this.jobLogs.get(key) ?? [];
    logs.push(...lines);
    this.jobLogs.set(key, logs);
  }

  async readJobLogs(runId: string, jobKey: string): Promise<JobLogLine[]> {
    const key = `${runId}:${jobKey}`;
    return [...(this.jobLogs.get(key) ?? [])];
  }

  getEvents(): LogEvent[] {
    return [...this.events];
  }
}

export class LogFnLogsAdapter implements LogsAdapter {
  constructor(private config: { baseUrl: string; apiKey?: string; sink?: string }) {}

  async emitEvent(event: LogEvent): Promise<void> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const sink = this.config.sink ?? 'cifn';
    const response = await fetch(`${this.config.baseUrl}/sinks/${sink}/events`, {
      method: 'POST',
      headers,
      body: JSON.stringify(event),
    });

    if (!response.ok) {
      throw new Error(`LogFn emitEvent failed: ${response.status} ${response.statusText}`);
    }
  }

  async appendJobLogLine(runId: string, jobKey: string, line: JobLogLine): Promise<void> {
    await this.appendJobLogLines(runId, jobKey, [line]);
  }

  async appendJobLogLines(runId: string, jobKey: string, lines: JobLogLine[]): Promise<void> {
    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
    };
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const sink = this.config.sink ?? 'cifn';
    const response = await fetch(`${this.config.baseUrl}/sinks/${sink}/logs/${runId}/${jobKey}`, {
      method: 'POST',
      headers,
      body: JSON.stringify({ lines }),
    });

    if (!response.ok) {
      throw new Error(`LogFn appendJobLogLines failed: ${response.status} ${response.statusText}`);
    }
  }

  async readJobLogs(runId: string, jobKey: string): Promise<JobLogLine[]> {
    const headers: Record<string, string> = {};
    if (this.config.apiKey) {
      headers['Authorization'] = `Bearer ${this.config.apiKey}`;
    }

    const sink = this.config.sink ?? 'cifn';
    const response = await fetch(`${this.config.baseUrl}/sinks/${sink}/logs/${runId}/${jobKey}`, {
      headers,
    });

    if (response.status === 404) {
      return [];
    }

    if (!response.ok) {
      throw new Error(`LogFn readJobLogs failed: ${response.status} ${response.statusText}`);
    }

    const result = await response.json() as { lines?: JobLogLine[] };
    return result.lines ?? [];
  }
}

export function createLogsAdapter(config: AdapterConfig['logs']): LogsAdapter {
  if (config.type === 'memory') {
    return new MemoryLogsAdapter();
  }

  if (!config.logfnBaseUrl) {
    throw new Error('LogFn adapter requires baseUrl');
  }

  return new LogFnLogsAdapter({
    baseUrl: config.logfnBaseUrl,
    apiKey: config.logfnApiKey,
    sink: config.logfnSink,
  });
}
