        additionalProperties: false,
      },
      annotations: { readOnlyHint: false, destructiveHint: false, idempotentHint: false, openWorldHint: false },
      metadata: { 'mcpfn/superconsole': { moduleId: 'superconsole', operationId: 'superconsole.confirmations.issue', safety: { classification: 'write', idempotent: false, audit: 'required' } } },
      handler: async (args, context, extra) => {
        const principal = extra.authInfo?.extra?.adminPrincipal;
        if (!principal || typeof principal !== 'object') throw new AdminError('unauthenticated', 'Authenticated Super Console MCP principal is required.');
        const receipt = await this.confirmOperation(String(args.operationId ?? ''), args.input ?? {}, {
          principal: principal as SuperConsolePrincipal,
          context: { ...context, source: 'mcp' },
        });
        return {
          content: [{ type: 'text', text: JSON.stringify(receipt) }],
          structuredContent: receipt,
        };
      },
    };
  }

  private async moduleRequest(request: Request, relative: string, state: SuperConsoleRequestState): Promise<Response> {
    const [, encodedModuleId, ...rest] = relative.split('/');
    const moduleId = decodeURIComponent(encodedModuleId ?? '');
    if (!this.registry.hasModule(moduleId)) throw new SuperConsoleHttpError(`${moduleId || 'The requested module'} is not enabled.`, { status: 404, code: 'MODULE_NOT_ENABLED' });
    if (rest.length === 0 && (request.method === 'GET' || request.method === 'HEAD')) {
      await this.authorizeShell('registry', state);
      const manifest = this.registry.requireManifest(moduleId);
      const view = this.moduleViewFor(manifest, state);
      if (view.capabilities.length === 0) {
        throw new SuperConsoleHttpError('No module capabilities are visible to the active operator.', { status: 404, code: 'MODULE_NOT_ENABLED' });
      }
      return this.headAware(request, success({
        module: view,
        summary: [
          { id: 'resources', label: 'Resources', value: view.resources.length },
          { id: 'operations', label: 'Operations', value: view.capabilities.length },
        ],
        notices: [],
      }, state.context.requestId));
    }

    const url = new URL(request.url);
    let matchedPath = url.pathname;
    const resourceAliasPath = rest[0] !== 'resources'
      ? `${this.registry.apiBasePath}/modules/${encodeURIComponent(moduleId)}/resources/${rest.join('/')}`
      : undefined;
    let entry = this.registry.matchRoute(request.method, matchedPath);
    let ciAliasKind: 'artifacts' | 'logs' | undefined;
    if (!entry && resourceAliasPath) {
      entry = this.registry.matchRoute(request.method, resourceAliasPath);
      if (entry) matchedPath = resourceAliasPath;
    }
    let aliasInput: Record<string, unknown> = {};
    if (moduleId === 'cifn' && request.method === 'GET') {
      const artifactMatch = /^runs\/([^/]+)\/artifacts$/.exec(rest.join('/'));
      const logMatch = /^runs\/([^/]+)\/jobs\/([^/]+)\/logs$/.exec(rest.join('/'));
      if (artifactMatch) {
        entry = this.registry.getOperation('cifn.artifacts.list');
        matchedPath = entry?.routePath ?? matchedPath;
        aliasInput = { filter: { runId: decodeURIComponent(artifactMatch[1]!) } };
        ciAliasKind = 'artifacts';
      } else if (logMatch) {
        entry = this.registry.getOperation('cifn.logs.list');
        matchedPath = entry?.routePath ?? matchedPath;
        aliasInput = { filter: { runId: decodeURIComponent(logMatch[1]!), jobKey: decodeURIComponent(logMatch[2]!) } };
        ciAliasKind = 'logs';
      }
    }
    if (!entry) {
      const ciAliasExists = moduleId === 'cifn' && (
        (/^runs\/[^/]+\/artifacts$/.test(rest.join('/')) && Boolean(this.registry.getOperation('cifn.artifacts.list')))
        || (/^runs\/[^/]+\/jobs\/[^/]+\/logs$/.test(rest.join('/')) && Boolean(this.registry.getOperation('cifn.logs.list')))
      );
      const methodExists = this.registry.operations.some((candidate) => candidate.moduleId === moduleId &&
        [matchedPath, resourceAliasPath].filter((path): path is string => Boolean(path)).some((path) =>
          this.registry.matchRoute(routeDefinition(candidate.operation).method, path)?.operation.id === candidate.operation.id));
      if (methodExists || ciAliasExists) throw new SuperConsoleHttpError('This module operation does not support the requested method.', { status: 405, code: 'METHOD_NOT_ALLOWED' });
    }
    if (!entry || entry.moduleId !== moduleId) throw new SuperConsoleHttpError('The requested module operation is not enabled.', { status: 404, code: 'OPERATION_NOT_ENABLED' });
    const input = { ...(await operationInput(request, entry, matchedPath)), ...aliasInput };
    const dispatched = await this.dispatcher.dispatch({ operationId: entry.operation.id, input, context: state.context });
    if (dispatched.ok !== false && ciAliasKind === 'artifacts') {
      const data = dispatched.data && typeof dispatched.data === 'object' && !Array.isArray(dispatched.data)
        ? dispatched.data as Record<string, unknown>
        : { value: dispatched.data };
      return response({ ...dispatched, data: { ...data, artifacts: (data.items as unknown[] | undefined) ?? [] } }, 200);
    }
    if (dispatched.ok !== false && ciAliasKind === 'logs') {
      const data = dispatched.data && typeof dispatched.data === 'object' && !Array.isArray(dispatched.data)
        ? dispatched.data as Record<string, unknown>
        : { value: dispatched.data };
      return response({ ...dispatched, data: { ...data, lines: (data.items as unknown[] | undefined) ?? [] } }, 200);
    }
    return resultResponse(dispatched);
  }

  private requirePermission(principal: SuperConsolePrincipal, permission: string): void {
    if (!this.hasPermission(principal.actor.permissions, permission)) {
      throw new SuperConsoleHttpError('The active operator lacks the required permission.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private hasPermission(permissions: readonly string[] | undefined, permission: string): boolean {
    return Boolean(permissions?.includes('*') || permissions?.includes(permission));
  }

  private async authorizeShell(surface: 'registry' | 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search', state: SuperConsoleRequestState): Promise<void> {
    if (!(await this.options.shellPolicy.authorize({ surface, principal: state.principal, context: state.context }))) {
      throw new SuperConsoleHttpError('The active operator cannot access this administration surface.', { status: 403, code: 'PERMISSION_DENIED' });
    }
  }

  private async authorizedSurfaces(state: SuperConsoleRequestState) {
    const policy = async (surface: 'overview' | 'api' | 'mcp' | 'settings' | 'audit' | 'search') =>
      this.options.shellPolicy.authorize({ surface, principal: state.principal, context: state.context });
    const hasPermission = (permission?: string) => !permission
      || state.principal.actor.permissions?.includes('*')
      || state.principal.actor.permissions?.includes(permission)
      || false;
    const [overview, api, mcp, settings, audit, search] = await Promise.all([
      policy('overview'),
      policy('api'),
      policy('mcp'),
      policy('settings'),
      policy('audit'),
      policy('search'),
    ]);
    return {
      overview: Boolean(overview) && hasPermission(this.options.overview?.permission),
      api: Boolean(api),
      mcp: Boolean(mcp) && this.mcpTools.some((tool) => this.mcpMetadataVisible(tool.metadata, state.context)),
      settings: Boolean(settings) && hasPermission(this.options.settings?.permission),
      audit: Boolean(audit) && Boolean(this.options.auditQuery) && hasPermission(this.options.auditQuery?.permission),
<script lang="ts">
  import { page } from '$app/state';
  import { invalidateAll } from '$app/navigation';
  import {
    ButtonLabel,
    ButtonRoot,
    ButtonSpinner,
  } from '@uifn/components-svelte/button';
  import {
    DialogBackdrop,
    DialogClose,
    DialogContent,
    DialogDescription,
    DialogPortal,
    DialogPositioner,
    DialogRoot,
    DialogTitle,
    DialogTrigger,
  } from '@uifn/components-svelte/dialog';
  import {
    FieldControl,
    FieldDescription,
    FieldError,
    FieldLabel,
    FieldRequiredIndicator,
    FieldRoot,
  } from '@uifn/components-svelte/field';
  import { FormActions, FormErrorSummary, FormRoot } from '@uifn/components-svelte/form';
  import { InputRoot } from '@uifn/components-svelte/input';
  import { SwitchControl, SwitchLabel, SwitchRoot, SwitchThumb } from '@uifn/components-svelte/switch';
  import { TextareaRoot } from '@uifn/components-svelte/textarea';
  import {
    createActionDraft,
    editableActionFields,
    validateActionInput,
    type ActionDraft,
    type ActionInputField,
    type ActionDraftValue,
  } from './action-form';
  import { fetchConsole, materializeAdminActionHref, safeAdminDownloadHref, scopedConsoleHref } from './admin-api';
  import { refreshSuccessfulMutation } from './mutation-outcome';
  import type { AdminActionViewModel } from './view-models';

  let {
    action,
    compact = false,
  }: { action: AdminActionViewModel; compact?: boolean } = $props();

  let running = $state(false);
  let result = $state<{ ok: boolean; message: string } | undefined>();
  let dialogOpen = $state(false);
  let draft = $state<ActionDraft>({});
  let errors = $state<Record<string, string>>({});
  let idempotencyKey: string | undefined;
  let idempotencyFingerprint: string | undefined;

  const fields = $derived(editableActionFields(action));
  const needsDialog = $derived(
    fields.length > 0 || action.requiresConfirmation === true || action.tone === 'danger'
  );

  function stableIdempotencyKey(input: Record<string, unknown>): string {
    const fingerprint = JSON.stringify(input);
    if (!idempotencyKey || idempotencyFingerprint !== fingerprint) {
      idempotencyKey = crypto.randomUUID();
      idempotencyFingerprint = fingerprint;
    }
    return idempotencyKey;
  }

  function resetDraft() {
    draft = createActionDraft(action);
    errors = {};
  }

  function setDraft(name: string, value: ActionDraftValue) {
    draft = { ...draft, [name]: value };
    if (errors[name]) {
      const { [name]: _removed, ...remaining } = errors;
      errors = remaining;
    }
  }

  function fieldId(field: ActionInputField): string {
    return `action-${action.id}-${field.name}`.replace(/[^a-zA-Z0-9_-]/g, '-');
  }

  function inputType(field: ActionInputField): string {
    if (field.type === 'number' || field.type === 'integer') return 'number';
    if (/(?:^|[-_])email$/i.test(field.name)) return 'email';
    if (/(?:^|[-_])(?:url|uri|href)$/i.test(field.name)) return 'url';
    if (/(?:password|passphrase|secret|token|credential|private[-_]?key|api[-_]?key|recovery[-_]?code)$/i.test(field.name)) return 'password';
    return 'text';
  }

  function scopedAdminEndpoint(endpoint: string | undefined, input: Record<string, unknown>, method: string): string | undefined {
    return safeAdminDownloadHref(materializeAdminActionHref(endpoint, input, method), {
      origin: page.url.origin,
      scope: page.url.searchParams,
    });
  }

  async function confirmationToken(input: Record<string, unknown>): Promise<string | undefined> {
    if (!action.requiresConfirmation) return undefined;
    const response = await fetchConsole(
      scopedConsoleHref('/api/admin/v1/confirmations', page.url.searchParams),
      {
        method: 'POST',
        headers: { accept: 'application/json', 'content-type': 'application/json' },
        body: JSON.stringify({ operationId: action.id, input }),
      }
    );
    const payload = await response.json().catch(() => undefined) as
      | { data?: { token?: string }; error?: { message?: string }; requestId?: string }
      | undefined;
    if (!response.ok || !payload?.data?.token) {
      const request = payload?.requestId ? ` (request ${payload.requestId})` : '';
      throw new Error(`${payload?.error?.message ?? 'The operation confirmation could not be issued.'}${request}`);
    }
    return payload.data.token;
  }

  async function runAction(input: Record<string, unknown>) {
    const method = (action.method ?? 'POST').toUpperCase();
    const endpoint = scopedAdminEndpoint(action.apiHref ?? action.href, input, method);
    if (!endpoint || action.disabled || running) {
      if (!endpoint) result = { ok: false, message: 'The action endpoint is not a trusted administration API URL.' };
      return;
    }
    running = true;
    result = undefined;
    try {
      const token = await confirmationToken(input);
      const headers = new Headers({ accept: 'application/json', 'content-type': 'application/json' });
      if (!['GET', 'HEAD'].includes(method)) headers.set('idempotency-key', stableIdempotencyKey(input));
      if (token) headers.set('x-admin-confirmation', token);
      const response = await fetchConsole(endpoint, {
        method,
        headers,
        body: ['GET', 'HEAD', 'DELETE'].includes(method) ? undefined : JSON.stringify(input),
      });
      const body = await response.json().catch(() => undefined) as
        | { error?: { message?: string }; message?: string; requestId?: string; auditId?: string; data?: { auditId?: string; requestId?: string } }
        | undefined;
      if (!response.ok) {
        const request = body?.requestId ? ` (request ${body.requestId})` : '';
        throw new Error(`${body?.error?.message ?? `HTTP ${response.status}`}${request}`);
      }
      const auditId = body?.auditId ?? body?.data?.auditId;
      const requestId = body?.requestId ?? body?.data?.requestId;
      const receipt = [
        auditId ? `Audit ${auditId}` : undefined,
        requestId ? `Request ${requestId}` : undefined,
      ].filter(Boolean).join(' · ');
      const successMessage = `${body?.message ?? `${action.label} completed.`}${receipt ? ` ${receipt}` : ''}`;
      idempotencyKey = undefined;
      idempotencyFingerprint = undefined;
      dialogOpen = false;
      result = await refreshSuccessfulMutation(successMessage, invalidateAll);
    } catch (cause) {
      result = {
        ok: false,
        message: cause instanceof Error ? cause.message : `${action.label} failed.`,
      };
    } finally {
      running = false;
    }
  }

  function submitDialog() {
    const validated = validateActionInput(action, draft);
    errors = validated.errors;
    if (!validated.ok) return;
    void runAction(validated.input);
  }

  function handleDialogOpen(open: boolean) {
    dialogOpen = open;
    if (open) {
      resetDraft();
      result = undefined;
    }
  }
</script>

{#if needsDialog}
  <DialogRoot open={dialogOpen} onOpenChange={handleDialogOpen} role={action.requiresConfirmation ? 'alertdialog' : 'dialog'}>
    <DialogTrigger
      class={`action-trigger ${action.tone === 'danger' ? 'action-trigger--danger' : ''}`}
      disabled={action.disabled}
    >
      {action.label}
    </DialogTrigger>
    <DialogPortal>
      <DialogBackdrop />
      <DialogPositioner>
        <DialogContent class="action-dialog">
          <DialogTitle>{fields.length ? action.label : `${action.label}?`}</DialogTitle>
          <DialogDescription>
            {action.description ?? 'This operator action is permission checked and recorded in the audit trail.'}
          </DialogDescription>
          <FormRoot
            class="action-form"
            invalid={Object.keys(errors).length > 0}
            onsubmit={(event: SubmitEvent) => {
              event.preventDefault();
              submitDialog();
            }}
          >
            {#each fields as field (field.name)}
              <FieldRoot class="action-form__field" required={field.required} invalid={Boolean(errors[field.name])}>
                {#if field.type === 'boolean'}
                  <SwitchRoot
                    class="action-form__boolean"
                    checked={draft[field.name] === true}
                    onCheckedChange={(checked: boolean) => setDraft(field.name, checked)}
                  >
                    <SwitchLabel>
                      {field.label}
                      {#if field.required}<FieldRequiredIndicator aria-label="required"> *</FieldRequiredIndicator>{/if}
                    </SwitchLabel>
                    <SwitchControl aria-describedby={field.description ? `${fieldId(field)}-description` : undefined}>
                      <SwitchThumb />
                    </SwitchControl>
                  </SwitchRoot>
                {:else}
                  <FieldLabel for={fieldId(field)}>
                    {field.label}
                    {#if field.required}<FieldRequiredIndicator aria-label="required"> *</FieldRequiredIndicator>{/if}
                  </FieldLabel>
                  {#if field.type === 'object' || field.type === 'array'}
                    <FieldControl>
                      <TextareaRoot
                        id={fieldId(field)}
                        value={typeof draft[field.name] === 'string' ? draft[field.name] : ''}
                        oninput={(event: Event) => setDraft(field.name, (event.currentTarget as HTMLTextAreaElement).value)}
                        required={field.required}
                        aria-invalid={Boolean(errors[field.name])}
                        aria-describedby={field.description ? `${fieldId(field)}-description` : undefined}
                        rows={5}
                        spellcheck="false"
                      />
                    </FieldControl>
                  {:else}
                    <FieldControl>
                      <InputRoot
                        id={fieldId(field)}
                        type={inputType(field)}
                        step={field.type === 'integer' ? '1' : field.type === 'number' ? 'any' : undefined}
                        value={typeof draft[field.name] === 'string' ? draft[field.name] : ''}
                        oninput={(event: Event) => setDraft(field.name, (event.currentTarget as HTMLInputElement).value)}
                        required={field.required}
                        aria-invalid={Boolean(errors[field.name])}
                        aria-describedby={field.description ? `${fieldId(field)}-description` : undefined}
                        autocomplete="off"
                      />
                    </FieldControl>
                  {/if}
                {/if}
                {#if field.description}<FieldDescription id={`${fieldId(field)}-description`}>{field.description}</FieldDescription>{/if}
                {#if errors[field.name]}<FieldError>{errors[field.name]}</FieldError>{/if}
              </FieldRoot>
            {/each}
            <FormErrorSummary>
              {Object.values(errors)[0] ?? 'Correct the highlighted action input.'}
            </FormErrorSummary>
            <FormActions class="action-dialog__actions">
              <DialogClose disabled={running}>Cancel</DialogClose>
              <ButtonRoot
                type="submit"
                variant={action.tone === 'danger' ? 'destructive' : 'primary'}
                disabled={running}
                loading={running}
              >
                <ButtonSpinner />
                <ButtonLabel>{running ? 'Working…' : action.requiresConfirmation ? `Confirm ${action.label}` : action.label}</ButtonLabel>
              </ButtonRoot>
            </FormActions>
          </FormRoot>
        </DialogContent>
      </DialogPositioner>
    </DialogPortal>
  </DialogRoot>
{:else}
  <ButtonRoot
    variant="outline"
    size={compact ? 'sm' : 'md'}
    disabled={action.disabled || running}
    loading={running}
    onclick={() => void runAction(action.input ?? {})}
  >
    <ButtonSpinner />
    <ButtonLabel>{action.label}</ButtonLabel>
  </ButtonRoot>
{/if}

{#if result}
  <span class:action-result--error={!result.ok} class="action-result" role="status">
    {result.message}
  </span>
import type { AdminJsonSchema } from '@superfunctions/admin';

export type AdminStateKind =
  | 'ready'
  | 'loading'
  | 'empty'
  | 'error'
  | 'forbidden'
  | 'not-found';

export type HealthTone = 'healthy' | 'degraded' | 'critical' | 'unknown';
export type ResourceTone = 'success' | 'warning' | 'danger' | 'info' | 'neutral';

export interface AdminErrorViewModel {
  status: number;
  code: string;
  message: string;
  requestId?: string;
  correlationId?: string;
  auditId?: string;
  details?: Record<string, unknown>;
  meta?: Readonly<Record<string, unknown>>;
}

export interface OperatorSessionViewModel {
  userId: string;
  displayName: string;
  email?: string;
  avatarUrl?: string;
  role: string;
  permissions?: string[];
  csrfCookieName?: string;
}

export interface ContextOptionViewModel {
  id: string;
  name: string;
  slug?: string;
}

export interface OperatorContextViewModel {
  organization?: ContextOptionViewModel;
  workspace?: ContextOptionViewModel;
  project?: ContextOptionViewModel;
  environment?: ContextOptionViewModel;
  organizations?: ContextOptionViewModel[];
  workspaces?: ContextOptionViewModel[];
  projects?: ContextOptionViewModel[];
  environments?: ContextOptionViewModel[];
}

export interface AdminActionViewModel {
  id: string;
  label: string;
  description?: string;
  input?: Record<string, unknown>;
  inputSchema?: AdminJsonSchema;
  targetIdInput?: string;
  sourceModuleId?: string;
  foldedIntoModuleId?: string;
  href?: string;
  apiHref?: string;
  method?: 'GET' | 'POST' | 'PUT' | 'PATCH' | 'DELETE';
  tone?: 'default' | 'danger';
  requiresConfirmation?: boolean;
  disabled?: boolean;
  permission?: string;
}

export interface AdminResourceViewModel {
